func newBackend(ctx context.Context, db *sql.DB, o options) (*Backend, error) {
	origin, err := httpsURL(o.Origin)
	if err != nil || origin.Path != "" || origin.RawQuery != "" || origin.ForceQuery {
		return nil, errors.New("browser backend requires an HTTPS origin")
	}
	if o.Upstream != "" || o.UpstreamCA != "" {
		return nil, errors.New("local application address is compiler-owned")
	}
	issuer, err := httpsURL(o.Issuer)
	if err != nil || cookieHost(issuer) == cookieHost(origin) {
		return nil, errors.New("browser issuer requires a separate HTTPS cookie host")
	}
	raw, err := client.ReadPrivateFile(o.KeyFile)
	if err != nil {
		return nil, errSession
	}
	keys, err := sessionKeys(raw)
	clear(raw)
	if err != nil {
		return nil, err
	}
	store, err := newStore(ctx, db, keys...)
	for _, key := range keys {
		clear(key)
	}
	if err != nil {
		return nil, err
	}
	upstream := client.NewLocalApplication()
	provider, err := discover(ctx, o)
	if err != nil {
		upstream.Close()
		return nil, err
	}
	authorization, _ := httpsURL(provider.metadata.Authorization)
	if cookieHost(authorization) == cookieHost(origin) {
		provider.close()
		upstream.Close()
		return nil, errors.New("browser authorization requires a separate HTTPS cookie host")
	}
	b := &Backend{store: store, provider: provider, upstream: upstream, origin: origin, permits: make(chan struct{}, client.MaxConcurrentRequests)}
	if json.Unmarshal([]byte(generatedConfiguration), &b.config) != nil {
		b.Close()
		return nil, errors.New("invalid generated browser configuration")
	}
	if b.config.LogoutScope == "identity_provider" {
		b.logoutTarget, b.logoutOrigin, err = provider.logoutTarget(origin)
		if err != nil {
			b.Close()
			return nil, err
		}
	}
	for _, route := range b.config.Routes {
		pattern := regexp.QuoteMeta(route)
		pattern = strings.ReplaceAll(pattern, `\{id\}`, `[^/]+`)
		compiled, err := regexp.Compile("^" + pattern + "$")
		if err != nil {
			b.Close()
			return nil, errors.New("invalid generated browser route")
		}
		b.routes = append(b.routes, compiled)
	}
	return b, nil
}
func (b *Backend) Close() {
	b.close.Do(func() { b.sockets.close(); b.sockets.wg.Wait(); b.provider.close(); b.upstream.Close() })
}
func (b *Backend) Run(ctx context.Context) error {
	defer func() { b.sockets.close(); b.sockets.wg.Wait() }()
	ticker := time.NewTicker(time.Minute)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return nil
		case <-ticker.C:
			work, cancel := context.WithTimeout(ctx, 5*time.Second)
			_ = b.store.sweep(work)
			cancel()
		}
	}
}
func cookieID(r *http.Request, name string) string {
	value := ""
	count := 0
	for _, cookie := range r.Cookies() {
		if cookie.Name == name {
			count++
			value = cookie.Value
		}
	}
	if count != 1 {
		return ""
	}
	if _, err := sessionHash(value); err != nil {
		return ""
	}
	return value
}
func setCookie(w http.ResponseWriter, name, value string, ttl int) {
	mode := http.SameSiteStrictMode
	if name == LoginCookie {
		mode = http.SameSiteLaxMode
	}
	http.SetCookie(w, &http.Cookie{Name: name, Value: value, Path: "/", MaxAge: ttl, Secure: true, HttpOnly: true, SameSite: mode})
}
func clearCookie(w http.ResponseWriter, name string) { setCookie(w, name, "", -1) }
func response(w http.ResponseWriter, code int, value any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(value)
}
func failure(w http.ResponseWriter, code int) {
	response(w, code, map[string]string{"error": http.StatusText(code)})
}
func (b *Backend) sameOrigin(r *http.Request) bool {
	return len(r.Header.Values("Origin")) == 1 && r.Header.Get("Origin") == b.origin.String()
}
func (b *Backend) browserPath(value string) bool {
	for _, route := range b.routes {
		if route.MatchString(value) {
			return true
		}
	}
	return false
}
func (b *Backend) returnPath(value string) string {
	u, err := url.Parse(value)
	if err != nil || len(value) > 2048 || u.IsAbs() || u.Host != "" || u.Fragment != "" || u.RawPath != "" || !b.browserPath(u.Path) || strings.ContainsAny(value, "\\\r\n\x00") {
		return "/"
	}
	return value
}
func (b *Backend) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Header().Set("Referrer-Policy", "no-referrer")
	w.Header().Set("Content-Security-Policy", "default-src 'none'; base-uri 'none'; frame-ancestors 'none'; object-src 'none'; script-src 'self'; style-src 'self'; img-src 'self' data:; font-src 'self'; connect-src 'self'; form-action 'self'")
	w.Header().Set("Strict-Transport-Security", "max-age=31536000")
	if socketRequest(r) {
		b.socket(w, r)
		return
	}
	select {
	case b.permits <- struct{}{}:
		defer func() { <-b.permits }()
	default:
		failure(w, 503)
		return
	}
	original := r
	defer func() { original.Pattern = r.Pattern }()
	ctx, cancel := context.WithTimeout(r.Context(), 20*time.Second)
	defer cancel()
	r = r.WithContext(ctx)
	if r.TLS == nil || r.Host != b.origin.Host || r.URL.RawPath != "" || len(r.URL.Path) > 4096 || len(r.URL.RawQuery) > 8192 || strings.ContainsAny(r.URL.Path, "\\\x00\r\n") {
		failure(w, 400)
		return
	}
	if len(r.Header.Values("Sec-Fetch-Site")) > 1 {
		failure(w, 400)
		return
	}
	if site := r.Header.Get("Sec-Fetch-Site"); site == "cross-site" || site == "same-site" {
		publicNavigation := (r.Method == "GET" || r.Method == "HEAD") && !strings.HasPrefix(r.URL.Path, "/auth/") && r.URL.Path != b.config.Prefix && !strings.HasPrefix(r.URL.Path, b.config.Prefix+"/")
		if r.URL.Path != "/auth/callback" && !(r.Method == "GET" && r.URL.Path == "/auth/logout") && !publicNavigation {
			failure(w, 403)
			return
		}
	}
	if len(r.Header.Values("Origin")) != 0 && !b.sameOrigin(r) {
		failure(w, 403)
		return
	}
	switch r.URL.Path {
	case "/auth/login":
		r.Pattern = "/auth/login"
		if r.Method != "GET" {
			w.Header().Set("Allow", "GET")
			failure(w, 405)
			return
		}
		b.login(w, r)
		return
	case "/auth/callback":
		r.Pattern = "/auth/callback"
		if r.Method != "GET" {
			w.Header().Set("Allow", "GET")
			failure(w, 405)
			return
		}
		b.callback(w, r)
		return
	case "/auth/session":
		r.Pattern = "/auth/session"
		if r.Method != "GET" {
			w.Header().Set("Allow", "GET")
			failure(w, 405)
			return
		}
		b.session(w, r)
		return
	case "/auth/logout":
		r.Pattern = "/auth/logout"
		if r.URL.RawQuery != "" {
			failure(w, 400)
			return
		}
		if r.Method == "GET" {
			b.confirmLogout(w, r)
			return
		}
		if r.Method != "POST" {
			w.Header().Set("Allow", "GET, POST")
			failure(w, 405)
			return
		}
		b.logout(w, r)
		return
	}
	if strings.HasPrefix(r.URL.Path, "/telemetry/") {
		r.Pattern = "/telemetry/v1/{signal}"
		b.telemetry(w, r)
		return
	}
	if r.URL.Path == b.config.Prefix || strings.HasPrefix(r.URL.Path, b.config.Prefix+"/") {
		r.Pattern = b.config.Prefix + "/{resource}"
		b.proxy(w, r)
		return
	}
	if r.Method != "GET" && r.Method != "HEAD" {
		failure(w, 405)
		return
	}
	target := r.URL.Path
	for i, route := range b.routes {
		if route.MatchString(target) {
			r.Pattern = b.config.Routes[i]
			target = "/index.html"
			break
		}
	}
	for _, a := range b.config.Assets {
		if a.Path == target {
			if _, ok := b.applicationSession(w, r); !ok {
				return
			}
			if target != "/index.html" {
				r.Pattern = "/assets/{asset}"
			} else if len(b.config.ScriptHashes) > 0 {
				w.Header().Set("Content-Security-Policy", strings.Replace(w.Header().Get("Content-Security-Policy"), "script-src 'self'", "script-src 'self' "+strings.Join(b.config.ScriptHashes, " "), 1))
			}
			body, err := assets.ReadFile("public" + target)
			if err != nil {
				failure(w, 500)
				return
			}
			contentType := "application/octet-stream"
			switch {
			case strings.HasSuffix(target, ".html"):
				contentType = "text/html; charset=utf-8"
			case strings.HasSuffix(target, ".js"):
				contentType = "text/javascript; charset=utf-8"
			case strings.HasSuffix(target, ".css"):
				contentType = "text/css; charset=utf-8"
			case strings.HasSuffix(target, ".svg"):
				contentType = "image/svg+xml"
			case strings.HasSuffix(target, ".png"):
				contentType = "image/png"
			case strings.HasSuffix(target, ".ico"):
				contentType = "image/x-icon"
			case strings.HasSuffix(target, ".woff2"):
				contentType = "font/woff2"
			case strings.HasSuffix(target, ".ttf"):
				contentType = "font/ttf"
			}
			hash := a.Hash
			if target == "/index.html" && (b.config.TelemetryService != "" || b.config.DynamicStyles) {
				at := b.config.RuntimeConfigOffset
				if at <= 0 || at > len(body) {
					failure(w, 500)
					return
				}
				var meta []byte
				if b.config.TelemetryService != "" {
					settings, _ := json.Marshal(telemetry.BrowserSettings(r.Context()))
					meta = append(meta, []byte(`<meta name="stego-runtime-config" content="`+html.EscapeString(string(settings))+`">`)...)
				}
				if b.config.DynamicStyles {
					nonce, err := randomValue()
					if err != nil {
						failure(w, 503)
						return
					}
					meta = append(meta, []byte(`<meta name="stego-style-nonce" content="`+nonce+`">`)...)
					w.Header().Set("Content-Security-Policy", strings.Replace(w.Header().Get("Content-Security-Policy"), "style-src 'self'", "style-src 'self' 'nonce-"+nonce+"'; style-src-attr 'none'", 1))
				}
				decorated := make([]byte, 0, len(body)+len(meta))
				decorated = append(decorated, body[:at]...)
				decorated = append(decorated, meta...)
				decorated = append(decorated, body[at:]...)
				body = decorated
				sum := sha256.Sum256(body)
				hash = hex.EncodeToString(sum[:])
			}
			w.Header().Set("Content-Type", contentType)
			tag := `"` + hash + `"`
			w.Header().Set("ETag", tag)

			if r.Header.Get("If-None-Match") == tag {
				w.WriteHeader(304)
				return
			}
			if r.Method == "GET" {
				_, _ = w.Write(body)
			}
			return
		}
	}
	failure(w, 404)
}

func cookieHost(u *url.URL) string {
	host := strings.TrimSuffix(strings.ToLower(u.Hostname()), ".")
	if ip := net.ParseIP(host); ip != nil {
		return ip.String()
	}
	return host
}
